namespace sv_264d9a2c28624d2abd6f1bdc1100fa49.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Components subscribe to OnChange to react to updates.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge" style="background-color: @ThemeService.AccentColor;">
    @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="d-flex align-items-center gap-2">
    <label>Theme:</label>
    <select class="form-select form-select-sm w-auto" @bind="CurrentTheme">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

@code {
    private ThemeMode CurrentTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4" style="max-width: 400px;">
    <div class="mb-3">
        <label class="form-label">Theme Mode</label>
        <select class="form-select" @bind="SelectedTheme">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               @bind="SelectedAccentColor" />
    </div>

    <button class="btn btn-primary" @onclick="Save"
            style="background-color: @ThemeService.AccentColor; border-color: @ThemeService.AccentColor;">
        Save Preferences
    </button>
</div>

<p class="mt-3 text-muted">
    Current: <strong>@ThemeService.Theme</strong> &mdash; Accent: 
    <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme;
    private string SelectedAccentColor = "#0d6efd";

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeService.Theme;
        SelectedAccentColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnThemeChanged;
    }

    private void Save()
    {
        ThemeService.Theme = SelectedTheme;
        ThemeService.AccentColor = SelectedAccentColor;
    }

    private void OnThemeChanged()
    {
        SelectedTheme = ThemeService.Theme;
        SelectedAccentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

